    print(f"Trying: {sessions_file}")
    try:
        content = open(sessions_file).read()
        if 'Correct' in content or 'Incorrect' in content or 'Wrong' in content:
            print("Found feedback keywords in session")
            for line in content.split('\n'):
                if 'Correct' in line or 'Incorrect' in line or 'Wrong' in line:
                    print(line)
    except:
        print("Could not read session file or no feedback found")

